{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import dedupe_sessions, daily_conversion_counts, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_ignores_empty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3], 1) == 3
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 10) == 6
    assert conversions_in_window([], 2) == 0


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    lines = ["  # comment, with commas", "", "  \t ", " a , 2 , 1 ",
             "b, -1, 0", "c, 3,   "]
    assert parse_session_log(lines) == [session("a", 2, True), session("b", -1, False),
                                        session("c", 3, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,nope,1", "a,1,yes"])
def test_parse_session_log_errors_report_input_line(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "", "  ", line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [session("a", 1, True), session("c", 2, True),
              session("b", 2, False), session("a", 2, None)]
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_counts_include_zero_days_and_ignore_outside_range():
    events = [session("a", 0, True), session("b", 1, True),
              session("c", 1, True), session("d", 2, None),
              session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 4, True), session("c", 5, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "b": [session("b", 1, False)], "a": [session("a", 1, True)]}
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [session("b", 1, False)], "a": [session("a", 1, True)]}
    result = conversion_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_or_negative_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0
